window.OSTEO_RA_EMBEDDED_DETAILS={"bySourceRow":{"2":{"source":"OSTPRA1 — ligne vidéo 2","titleSource":"DYSFONCTION DE ILIUM, en antériorité à gauche","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les mains derrière la tête, les doigts sont croisés. Le membre inférieur homolatéral à la dysfonction est posé sur le membre inférieur controlatéral. PRATICIEN Debout, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphalique sont sur la ceinture scapulaire homolatérale à la dysfonction; la main caudale est posée sur l’épine ilium antéro-supérieure du côté de la dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la ceinture scapulaire dans un plan perpendiculaire à la table et exercer une légère traction dans l’axe vertébral. Stabiliser la position avec la main céphalique. La main caudale empaume l’épine ilium antéro-supérieure du côté à traiter et ramène le pelvis au contact de la table. Amener l’ilium vers la postériorisation jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans la direction de la postériorisation de l’ilium."}],"images":[]},"3":{"source":"OSTPRA1 — ligne vidéo 3","titleSource":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (variante sujet laxe)","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. Le membre inférieur du côté à traiter est en flexion de hanche et de genou à 90°. Le membre inférieur sur la table est en rectitude. PRATICIEN Debout, face au patient, entre les membres inférieurs du patient à la hauteur du pelvis en fente avant en direction de la tête du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La cuisse gauche du patient est soutenue par le bassin du praticien. Les mains sont en pronation empaumant l’ischium et l’épine ilium antéro-supérieure du côté à traiter."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion de hanche pour amener l’ilium vers la postériorité jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la postériorisation de l’ilium."}],"images":[]},"4":{"source":"OSTPRA1 — ligne vidéo 4","titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à gauche","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral, controlatéral à l’ilium en dysfonction. Le membre inférieur du côté à traiter est en triple flexion (pied à la hauteur de la fosse poplitée du genou droit). PRATICIEN Debout à la hauteur du pelvis, face au patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est sous le creux axillaire et maintient l’épaule du patient en haut et en arrière. La main caudale est en regard de l’épine ilium postéro-supérieure, les doigts sont orientés dans le sens de la crête iliaque. Placer le genou du patient entre les membres inférieurs du praticien afin de stabiliser la flexion et organiser la barrière motrice."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le rachis dans l’axe et stabiliser la position avec la main céphalique. Rechercher la barrière motrice de la flexion vers l’extension de la hanche jusqu’à percevoir la mise en tension de l’ilium vers l’antériorité."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en direction de l’antériorisation de l’ilium."}],"images":[]},"5":{"source":"OSTPRA1 — ligne vidéo 5","titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite (variante sujet laxe)","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. PRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur à traiter par la main caudale. La paume de la main céphalique est sur l’épine ilium postéro-supérieure du côté à traiter. Les doigts sont orientés vers la crête iliaque."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur à traiter en extension, en adduction et en rotation interne jusqu’à la barrière motrice en antériorité."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique sur l’épine ilium postéro-supérieure vers l’antériorité de l’ilium."}],"images":[]},"6":{"source":"OSTPRA1 — ligne vidéo 6","titleSource":"DYSFONCTION DE L’ILIUM, en supériorité à droite","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. Le membre inférieur à traiter est en légère abduction et rotation interne. PRATICIEN Debout face aux pieds du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la cheville, la main externe étant en supination et la main interne en pronation."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère extension, abduction et en rotation interne puis exercer une traction jusqu’à percevoir la barrière motrice une traction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en traction dans l’axe du membre inférieur."}],"images":[]},"8":{"source":"OSTPRA1 — ligne vidéo 8","titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal le membre inférieur droit est en dehors de la table. PRATICIEN Debout à la hauteur du pelvis"},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume et fixe l’épine ilium antéro- supérieure controlatérale à la dysfonction, la main caudale est posée sur le dessus du genou homolatéral, les doigts sont orientés vers le dehors."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère abduction et en extension de hanche jusqu’à la barrière motrice en antériorité (contrôler au niveau de l’épine iliaque postéro-supérieure)."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en flexion de hanche contre résistance pendant 10 à 12 secondes puis gagner vers la nouvelle barrière motrice en extension de hanche – à répéter 3 fois."}],"images":[]},"9":{"source":"OSTPRA1 — ligne vidéo 9","titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite en procubitus (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. PRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur droit par la main caudale, et de la main céphalique contacter l’épine ilium postéro- supérieure et la partie postérieure de la crête iliaque. Les doigts sont orientés vers la crête iliaque."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en extension, en adduction et en légère rotation interne jusqu’à la barrière motrice en antériorité."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander une flexion de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en antériorité – à répéter 3 fois."}],"images":[]},"10":{"source":"OSTPRA1 — ligne vidéo 10","titleSource":"DYSFONCTION DE L’ILIUM, en fermeture à droite (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur à traiter est en flexion, en abduction, en rotation externe de hanche et en flexion de genou. PRATICIEN Debout à la hauteur du pelvis, le regard est dirigé vers les pieds du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer et fixer l’épine ilium antéro-supérieure controlatérale par la main céphalique et saisir la cheville homolatérale avec la main caudale. Le coude est en contact avec la face interne du genou."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion, l’abduction et la rotation externe de hanche jusqu’à la barrière motrice de la sacro-ilium droite en ouverture."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation interne et en adduction pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en ouverture en rotation externe – à répéter 3 fois. À la fin, reposer le membre inférieur en perdant les paramètres dans l’ordre : d’abord la flexion puis l’abduction et enfin la rotation externe qui est maintenue jusqu’à la fin de la technique."}],"images":[]},"11":{"source":"OSTPRA1 — ligne vidéo 11","titleSource":"DYSFONCTION DE L’ILIUM, en ouverture à droite (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur du patient du côté à traiter est en flexion, en adduction, en rotation interne de hanche et en flexion de genou. PRATICIEN Debout à la hauteur du pelvis en fente avant. Les épaules sont dirigées vers la tête du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le bord interne de l’épine ilium postéro-supérieure gauche, la main caudale empaume le pied homolatéral à la dysfonction par sa face interne. L’épaule caudale du praticien prend appui sur la face externe du genou du patient."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en flexion, en adduction et en rotation interne avec le genou fléchi jusqu’à la barrière motrice jusqu’à percevoir la fermeture de l’ilium."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation externe et en légère abduction contre résistance pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en fermeture en rotation interne – à répéter 3 fois – À la fin, perdre les paramètres dans l’ordre : d’abord la flexion, puis l’adduction et enfin la rotation interne qui est maintenue jusqu’à la fin de la technique."}],"images":[]},"12":{"source":"OSTPRA1 — ligne vidéo 12","titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure avec le pisiforme direct, à gauche","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus controlatéral à la dysfonction, le membre inférieur controlatéral est en extension, l’homolatéral est en légère flexion de hanche et de genou. PRATICIEN Debout à la hauteur du pelvis du patient. La main caudale est placée sur l’espace inter-épineux L5-S1."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte avec le pisiforme l’articulation sacro-ilium en dysfonction, la main céphalique est en contact avec le sillon delto-pectoral du membre supérieur sus-jacent."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tracter dans l’axe vertébral le rachis du patient jusqu’à solliciter l’espace inter-épineux L5-S1. Inviter le patient à croiser les doigts sur son thorax. Majorer la flexion de la hanche du genou du côté à traiter jusqu’à solliciter l’articulation sacro-ilium en dysfonction. Stabiliser la position du membre inférieur homolatéral en plaçant le pied du patient dans la fosse poplitée du membre inférieur en rectitude, le genou reste en dehors de la table."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur la base sacrée à l’aide du pisiforme et simultanément sur le genou du patient dans l’axe de la cuisse pour obtenir une ouverture de l’articulation sacro-ilium."}],"images":[]},"13":{"source":"OSTPRA1 — ligne vidéo 13","titleSource":"DYSFONCTION DU SACRUM, en flexion unilatérale sur axe horizontal, à gauche","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté opposé à la dysfonction. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main céphalique l’aileron inféro-latéral homolatéral à la dysfonction, la main caudale est superposée à la main céphalique."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur homolatéral en légère abduction, en rotation interne, pour ouvrir l’articulation sacro-ilium. Avant la manœuvre demander au sujet de tourner la tête du côté de la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Majorer la barrière motrice d’extension unilatérale du sacrum en augmentant la pression de la main caudale sur la main céphalique et porter un thrust en fin d’inspiration vers le bas et l’avant du sujet."}],"images":[]},"14":{"source":"OSTPRA1 — ligne vidéo 14","titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur axe oblique droit","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les mains derrière la tête, les doigts sont croisés et les coudes dirigés vers avant. PRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique fixe la position de la ceinture scapulaire par un appui sur la scapula. La main caudale placée sur l’épine ilium antéro- supérieure homolatérale ramène le pelvis au contact de la table"},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Dans un premier temps, amener une concavité opposée à la dysfonction par les membres inférieurs tendus en contrôlant L5-S1 jusqu’à son engagement. Dans un deuxième temps, amener la ceinture scapulaire du patient dans un plan perpendiculaire à la table. Exercer à partir de celle-ci une traction dans l’axe vertébral et la placer légèrement en retrait par rapport au pelvis. Fixer le pelvis contre la table avec la main caudale et majorer la traction et la rotation du tronc jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration avec la main céphalique depuis la ceinture scapulaire par le levier supérieur en traction et en rotation."}],"images":[]},"15":{"source":"OSTPRA1 — ligne vidéo 15","titleSource":"DYSFONCTION DU SACRUM, en torsion antérieure droite sur axe droit (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée vers le praticien. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Maintenir les chevilles par la main caudale, soutenir les cuisses du patient à l’aide de sa cuisse caudale, la main céphalique contrôle la sacro-ilium."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le patient à faire une extension des membres inférieurs en maintenant de son avant-bras caudale les chevilles du patient afin de les décoller du plan de la table dans le but de glisser son avant-bras céphalique en regard du 1/3 inférieur des cuisses du patient. Effectuer une traction des genoux du patient vers le dehors de la table afin de placer le pelvis du patient à 90° sur la table, le buste restant installé sur la table en procubitus."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à lever les pieds vers le plafond pendant 10 à 12 secondes, contre résistance, en contrôlant la sacro-ilium. Au relâchement chercher une nouvelle barrière motrice par un abaissement des pieds vers le sol – à répéter 3 fois."}],"images":[]},"16":{"source":"OSTPRA1 — ligne vidéo 16","titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur un axe droit (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus couché sur l’axe en dysfonction du sacrum. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique contrôle l’articulation sacro-ilium au niveau de son sillon. La main caudale est en contact avec la face externe de la cuisse sus-jacente."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral et amener en légère lordose lombaire. Tracter le membre supérieur sur la table vers le haut et l’avant du sujet de façon à déroter le sujet jusqu’à L5-S1. Demander au patient de croiser ses bras. Faire glisser le membre inférieur sur la table jusqu’à la barrière motrice en extension. Amener le membre inférieur opposé à la table en flexion et en adduction de hanche, en gardant le genou tendu jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser le genou opposé à la table vers le plafond contre résistance pendant 10 à 12 secondes. Au relâchement, chercher la nouvelle barrière motrice en abaissement du membre inférieur – à répéter 3 fois."}],"images":[]},"17":{"source":"OSTPRA1 — ligne vidéo 17","titleSource":"DYSFONCTION DU SACRUM, en antériorité unilatérale. Manœuvre avec le pisiforme directe sur l’aileron inféro-latéral, à gauche","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le sillon delto-pectoral, la main caudale contacte par le pisiforme l’aileron inféro- latéral opposé à la table."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral. Tracter le membre supérieur sur la table de façon à déroter le tronc du patient jusqu’à L5-S1. Demander une rotation de la tête vers le plafond. Le membre inférieur sur la table est amené en extension, le membre inférieur opposé à la table est en flexion, le pied fixé dans la fosse poplitée."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec le pisiforme en direction céphalique."}],"images":[]},"19":{"source":"OSTPRA1 — ligne vidéo 19","titleSource":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en supériorité à droite (E.M.)","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"Pelvis – symphyse pubienne. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. Le membre inférieur homolatéral à la dysfonction est en dehors de la table et est maintenu entre les jambes du praticien. PRATICIEN Debout à la hauteur du pelvis les épaules sont dirigées vers la tête du sujet, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’épine iliaque antéro-supérieure controlatérale. La main homolatérale à la dysfonction enserre la face antérieure et distale de la cuisse."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer l’extension de la hanche jusqu’à la barrière motrice de la symphyse pubienne."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fléchir la hanche en lui demandant de pousser le genou vers le plafond pendant 10 à 12 secondes et s’y opposer – À répéter trois fois."}],"images":[]},"20":{"source":"OSTPRA1 — ligne vidéo 20","titleSource":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en infériorité à gauche (E.M.)","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"Pelvis – symphyse pubienne. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le membre inférieur homolatéral à la dysfonction est en flexion. PRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique saisit le bord opposé de la table. Le creux axillaire homolatéral est en appui sur le genou du sujet, homolatéral à la dysfonction. La main caudale, poing fermé, forme un coin sous la tubérosité ischiatique du sujet du côté de la dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en flexion sur le thorax. Majorer la flexion de hanche jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une extension de hanche et s’y opposer. Rechercher ensuite la nouvelle barrière motrice vers la flexion en s’aidant du coin constitué par la main caudale – À répéter 3 fois."}],"images":[]},"21":{"source":"OSTPRA1 — ligne vidéo 21","titleSource":"DYSFONCTION COMBINÉE DE LA SYMPHYSE PUBIENNE, en supériorité et infériorité (E.M.)","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"Pelvis – symphyse pubienne. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les genoux sont fléchis les pieds sont posés sur la table. PRATICIEN Assis sur les pieds du sujet, les épaules sont dirigées vers la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Dans un premier temps, empaumer la face externe des genoux joints. Puis, dans un deuxième temps, placer les avant-bras entre les genoux."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir les deux genoux accolés."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une abduction des hanches et s’y opposer. Relâcher soudainement la pression sur les genoux et bloquer l’abduction des hanches par les coudes – À répéter 3 fois. Puis, intercaler l’avant-bras entre les genoux, demander une adduction, libérer vivement l’avant-bras et bloquer les deux genoux par le coude."}],"images":[]},"22":{"source":"OSTPRA1 — ligne vidéo 22","titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en NSR à droite","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la dysfonction est sur la table, les membres inférieurs sont fléchis. PRATICIEN Debout face au sujet à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale est en contact avec l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro- postérieure de la fesse gauche. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus- jacente à la dysfonction. L’avant- bras céphalique est posé au niveau du sillon delto- pectoral sus-jacent et fixe la rotation du tronc."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en extension. Le membre inférieur sous-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous-jacent jusqu’à solliciter l’espace inter- épineux concerné. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Porter le thrust sur la phase expiratoire."}],"images":[]},"23":{"source":"OSTPRA1 — ligne vidéo 23","titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en ERS à droite","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis. PRATICIEN Debout face au sujet à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto- pectoral sus-jacent et fixe la rotation du tronc."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou sous-jacent en extension et maintenir une légère flexion de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent en rotation du tronc jusqu’à solliciter l’espace inter-épineux concerné. Ajouter une composante de flexion du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire."}],"images":[]},"24":{"source":"OSTPRA1 — ligne vidéo 24","titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en FRS à droite","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis. PRATICIEN Debout face au sujet à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus‑jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sous‑jacent en rectitude avec une extension de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent jusqu’à solliciter l’espace inter‑épineux concerné. Ajouter une composante d’extension du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens d’une rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire,"}],"images":[]},"25":{"source":"OSTPRA1 — ligne vidéo 25","titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, assis, à gauche","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table. Le patient met sa main opposée à la dysfonction sur son épaule homolatérale à la dysfonction. L’autre main est posée sur le ventre. PRATICIEN La table est en position basse, le praticien est assis à califourchon dans le dos du sujet légèrement du coté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien contacte l’épaule opposée du patient. Le pisiforme de la main caudale contacte la transverse de la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en légère flexion, en rotation et en inclinaison droite jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation opposée à la dysfonction sur la phase expiratoire."}],"images":[]},"26":{"source":"OSTPRA1 — ligne vidéo 26","titleSource":"DYSFONCTION DES LOMBAIRES, en NSR à gauche (E.M.)","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"Lombaire – lombaire. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposée à la dysfonction. Les genoux et les hanches sont fléchis à 90°. La main du membre supérieur sus-jacent attrape le bord supérieur de la table. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique la vertèbre en dysfonction. La main caudale soutient les chevilles."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Lever vers le plafond les chevilles de façon à corriger la latéroflexion lombaire jusqu’au niveau concerné."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’abaisser les pieds vers le sol et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par l’élévation des pieds – À répéter trois fois."}],"images":[]},"27":{"source":"OSTPRA1 — ligne vidéo 27","titleSource":"DYSFONCTION DES LOMBAIRES, en ERS à gauche (E.M.)","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"Lombaire – lombaire. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus. La tête est tournée du côté de la dysfonction. Les hanches et genoux sont amenés par le praticien en flexion à 90° en dehors de la table. Le bras opposé à la dysfonction est le long de la table. Le bras homolatéral est pendant en dehors de la table. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale soutient les chevilles."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener en flexion les hanches et s’arrêter juste avant d’entraîner la vertèbre en dysfonction. Demander au sujet de pousser le membre supérieur en dehors de la table vers le sol. Amener les pieds vers le sol et s’arrêter juste avant d’entraîner la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de lever les pieds vers le plafond et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par abaissement des pieds et flexion des hanches. Demander au sujet de glisser le membre supérieur posé sur la table vers ses pieds, et le membre supérieur en dehors de la table vers le sol – À répéter trois fois."}],"images":[]},"28":{"source":"OSTPRA1 — ligne vidéo 28","titleSource":"DYSFONCTION DES LOMBAIRES, en FRS à droite","category":"Lombaire – lombaire","method":"Technique structurelle","intro":"Lombaire – lombaire. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté de la dysfonction. La tête est tournée vers le haut. Le membre inférieur sous‑jacent est amené en extension. Le membre inférieur sus‑jacent est en extension de hanche, genoux à 90°. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale saisit la jambe sus-jacente du patient."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le membre supérieur sous-jacent pour engendrer une rotation du tronc. Demander au sujet de maintenir cette position en saisissant le bord opposé de la table avec sa main. Amener la hanche sus-jacente en rotation interne, en extension et en abduction. S’arrêter juste avant d’entraîner dans ce mouvement la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à faire une flexion de hanche gauche et s’y opposer, pendant 10 à 12 secondes. Puis, au relâchement rechercher de la nouvelle barrière motrice par une extension de la hanche – À répéter trois fois. Puis, inviter le sujet à faire une adduction de la hanche et s’y opposer. Au relâchement, chercher la nouvelle barrière motrice par une abduction de la hanche – À répéter trois fois."}],"images":[]},"29":{"source":"OSTPRA1 — ligne vidéo 29","titleSource":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique en double appui","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les membres supérieurs sont croisées sur le thorax. La main gauche est sur l’épaule droite et la main droite est sur l’épaule gauche. Les coudes sont superposés, le coude droit est au dessus de l’autre. PRATICIEN Debout à la hauteur du pelvis, les épaules sont orientées vers la tête du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique soutient le thorax et la tête. La main caudale par un double appui (éminence thénar et 2e phalanges des 4 derniers doigts) est en regard des apophyses transverses de la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le sujet en flexion du tronc puis amener le sujet au contact de la main du praticien en allongeant le patient sur la table."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice. Le thrust sera porté au passage de la vertèbre en dysfonction sur le double contact de la main applicatrice du praticien sur la phase expiratoire."}],"images":[]},"30":{"source":"OSTPRA1 — ligne vidéo 30","titleSource":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique indirecte à droite en « Lumbar Roll »","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus droit. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"L’avant-bras caudal contacte la face postéro-externe de la fesse sus-jacente du patient. La main caudale contacte la zone en dysfonction. L’avant-bras céphalique contacte le sillon delto‑pectoral sus-jacent du patient, la main céphalique est sur la zone en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sus-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Amener le levier supérieur en rotation jusqu’à la zone en dysfonction. Amener le levier inférieur en rotation opposée. Fixer les leviers en amenant le sujet sous le praticien. Porter le thrust en exagération du levier inférieur sous le levier supérieur sur la phase expiratoire."}],"images":[]},"31":{"source":"OSTPRA1 — ligne vidéo 31","titleSource":"DYSFONCTION DE L3, technique semi-directe à gauche en « Lumbar Roll »","category":"Lombaire – lombaire","method":"Thrust","intro":"Lombaire – lombaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la postériorité de la vertèbre est positionnée vers le haut. PRATICIEN Debout à la hauteur du pelvis."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"L’index de la main caudale contacte la transverse de la vertèbre en dysfonction. La main céphalique maintient les poignets du patient."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sous-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sus-jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en exagérant le levier de rotation."}],"images":[]},"32":{"source":"OSTPRA1 — ligne vidéo 32","titleSource":"CHARNIÈRE D12/L1, technique en « Lift », postériorité à gauche","category":"Lombaire – lombaire","method":"Lift","intro":"Lombaire – lombaire. Lift.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table, les pieds sont posés au sol. La face dorsale de la métacarpo-phalangienne de l’index de la main du côté de la dysfonction contacte la transverse postérieure. La main est ouverte, le pouce est dirigé vers le haut. L’autre main est superposée de la même manière. PRATICIEN Assis à califourchon derrière du sujet, les pieds sont posés au sol."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Passer le membre supérieur sous le bras du sujet pour fixer le thorax et l’abdomen. La main opposée à la dysfonction contacte l’arrière de la tête pour contrôler la flexion du tronc. Le contacteur représenter par le sternum du praticien est au contact sur les mains du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener de thorax en flexion jusqu’au niveau de la dysfonction. Fixer la position des leviers par le contact sternal. Amener dans un mouvement en virgule le thorax en compression vers le praticien puis le tracter vers le haut dans un mouvement de décoaptation."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans un mouvement de traction verticale (lift) lors de l’expiration."}],"images":[]},"33":{"source":"OSTPRA2 — ligne vidéo 33","titleSource":"Dysfonction facettaire des dorsaleS, en flexion, technique en double appui","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude côté praticien est placé au dessus de l’autre. PRATICIEN Debout à la hauteur du thorax."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet vers soi de façon à localiser par la main caudale la vertèbre en dysfonction. Placer les transverses des vertèbres en dysfonction entre son éminence thénar et ses doigts fléchis, le pouce est dans l’axe vertébral en direction de la tête du sujet. Puis maintenir par la main céphalique et le thorax les coudes et le thorax du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’inspiration vers la table."}],"images":[]},"34":{"source":"OSTPRA2 — ligne vidéo 34","titleSource":"Dysfonction facettaire des dorsales, en extension, technique en double appui","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax les coudes sont superposés. Le coude côté praticien est placé au dessus de l’autre. PRATICIEN Debout à la hauteur du thorax."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la vertèbre en dysfonction. Puis, contacter les transverses des vertèbres en dysfonction par l’éminence thénar et les phalangines de la main caudale, le pouce est dans l’axe vertébral vers la tête du sujet. La main et l’avant-bras céphalique soulèvent et soutiennent la tête et le rachis dorsal haut. Le sternum du praticien contacte les coudes du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table dans un mouvement de virgule vers la tête du sujet, en fin d’expiration."}],"images":[]},"35":{"source":"OSTPRA2 — ligne vidéo 35","titleSource":"Dysfonction facettaire DES dorsaleS, technique en simple appui","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude du côté du praticien est placé au dessus de l’autre. PRATICIEN Debout à la hauteur du thorax."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter la transverse en postériorité de la vertèbre en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral en direction de la tête, la main reste à plat. Verrouiller les coudes du sujet par un appui sternal."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration vers le plan de la table."}],"images":[]},"36":{"source":"OSTPRA2 — ligne vidéo 36","titleSource":"Dysfonction facettaire DES dorsaleS, avec les pisiformes croisés, postériorité à droite","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction. PRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité de la vertèbre en dysfonction. Contacter par le pisiforme de la main céphalique l’apophyse transverse de la vertèbre sous-jacente en créant ainsi un contre appui."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en fin d’expiration, en direction de la tête du sujet et du sol, dans le plan des facettes articulaires."}],"images":[]},"37":{"source":"OSTPRA2 — ligne vidéo 37","titleSource":"Dysfonction facettaire Des dorsales, technique en pisiforme simple, postériorité à droite","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction. PRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité. Renforcer ce contact en plaçant le pisiforme de la main céphalique au niveau de la tabatière anatomique de la main applicatrice."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale, en fin d’expiration, en direction de la tête du sujet et du sol dans le plan des facettes articulaires."}],"images":[]},"38":{"source":"OSTPRA2 — ligne vidéo 38","titleSource":"Dysfonction facettaire(s) des dorsale(s) (D9 à D12), assis, technique en pisiforme simple, postériorité à gauche","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dorsales et thorax – dorsale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, la main opposée à la dysfonction est posée sur l’épaule du côté de la dysfonction. L’autre main est posée sur le ventre. PRATICIEN Assis à califourchon sur la table derrière le sujet, légèrement décalé du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’épaule et la main du sujet du côté de la dysfonction. Le pisiforme de la main caudale contacte la postériorité de la vertèbre en dysfonction. Les doigts sont posés sur le grill costal."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener, par la main céphalique, le levier supérieur thoracique en rotation et en inclinaison opposées à la dysfonction jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par le pisiforme de la main caudale en exagérant le levier de rotation, en fin d’expiration."}],"images":[]},"39":{"source":"OSTPRA2 — ligne vidéo 39","titleSource":"Dysfonction facettaire DES dorsales, technique en « double Nelson »","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dorsales et thorax – dorsale. Lift.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table. PRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Glisser les mains sous les bras du sujet pour se saisir des poignets. Demander au sujet de croiser les doigts derrière la nuque et accompagne le mouvement."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de serrer les coudes jusqu’à ressentir la mise en tension de la zone en dysfonction. Amener le rachis cervical en flexion jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift) en fin d’expiration."}],"images":[]},"40":{"source":"OSTPRA2 — ligne vidéo 40","titleSource":"Dysfonction(s) des vertèbre(s) dorsale(s), technique en « lift » (composantes multiples) assis","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dorsales et thorax – dorsale. Lift.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, les bras sont croisés sur le thorax les coudes sont superposés. Le rachis cervical est en flexion. PRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer avec les deux mains le coude inférieur du sujet. Puis placer son sternum en contact direct avec la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la zone en dysfonction contre le sternum du praticien par un mouvement de virgule, vers l’arrière et vers le haut, jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift), en fin d’expiration."}],"images":[]},"41":{"source":"OSTPRA2 — ligne vidéo 41","titleSource":"Dysfonction d’une vertèbre dorsale (D8-D12), en NSgRd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds posés au sol, les bras sont croisés sur le thorax. PRATICIEN Assis derrière le sujet du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer par la main céphalique l’épaule du sujet du côté de la dysfonction. Contacter par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de s’incliner du côté de la vertèbre en dysfonction. Puis, amener le thorax en rotation opposée jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une inclinaison du tronc dans le sens opposé à la dysfonction, et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison du côté de la dysfonction et en rotation opposée – À répéter trois fois."}],"images":[]},"42":{"source":"OSTPRA2 — ligne vidéo 42","titleSource":"Dysfonction d’une vertèbre dorsale (D7-D12) en ERdSd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière la tête. PRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe par l’anneau formé par le membre supérieur controlatéral à la dysfonction pour rejoindre l’omoplate du côté de la dysfonction. Contacter, par la main caudale, l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis dorsal en latéroflexion, en rotation du côté opposé à la dysfonction et y associer une translation controlatérale jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe à l’apex de la courbure."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en latéroflexion, en rotation et en flexion dans le sens opposé à la dysfonction – À répéter trois fois."}],"images":[]},"43":{"source":"OSTPRA2 — ligne vidéo 43","titleSource":"Dysfonction d’une vertèbre dorsale (D8-D12), en FRdSd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. La main du côté de la dysfonction est posée sur l’épaule opposée, l’autre main est posée sur la table. PRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le deltoïde du sujet du côté de la dysfonction. Placer la main caudale sur l’espace inter-épineux sous-jacent à la vertèbre dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à effectuer une extension, une inclinaison par un abaissement de l’épaule et une rotation du côté opposé à la dysfonction ainsi qu’une translation controlatérale du tronc jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe alors à l’apex de la courbure."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison et en rotation – À répéter trois fois."}],"images":[]},"44":{"source":"OSTPRA2 — ligne vidéo 44","titleSource":"Dysfonction d’une vertèbre dorsale (D4-D8), en NSgRd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière le cou. PRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe sous le coude proximal du sujet puis par l’anneau formé par le membre supérieur distal pour venir se poser sur l’épaule du côté de la dysfonction. La main caudale contacte l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en inclinaison du côté de la dysfonction par l’abaissement de l’épaule homolatérale et une élévation de l’épaule controlatérale. Amener une translation du côté opposé à la dysfonction du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Tracter par la main céphalique l’épaule homolatérale à la dysfonction vers l’avant jusqu’à percevoir la rotation de la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale à la dysfonction et en rotation controlatérale – À répéter trois fois."}],"images":[]},"45":{"source":"OSTPRA2 — ligne vidéo 45","titleSource":"Dysfonction d’une vertèbre dorsale (D4-D8), en FRdSd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté opposé à la postériorité de la vertèbre en dysfonction. Amener le membre supérieur homolatéral à la dysfonction le long de la tête, le coude fléchi. Le membre supérieur controlatéral reste le long du corps. Croiser la cheville homolatérale à la dysfonction sur l’autre cheville. PRATICIEN Debout à la hauteur du thorax."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité, les doigts sont en direction de la tête du sujet. Le pisiforme de la main céphalique contacte l’apophyse transverse controlatérale de la même vertèbre. Les doigts sont dirigés vers les pieds du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Augmenter la pression des deux mains de façon à majorer la rotation de l’apophyse transverse en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander une respiration profonde et profiter de la phase expiratoire pour exercer, par la main caudale, une pression sur l’apophyse transverse en postériorité en direction de la tête du sujet et du sol dans le plan des facettes articulaires. Exercer simultanément une pression, par la main céphalique, sur l’apophyse transverse opposée en direction des pieds du sujet. Au relâchement rechercher la nouvelle barrière motrice en exagérant les leviers d’inclinaison – À répéter trois fois."}],"images":[]},"46":{"source":"OSTPRA2 — ligne vidéo 46","titleSource":"Dysfonction d’une vertèbre dorsale (D1-D4), en NSgRd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. PRATICIEN Debout derrière le sujet. Poser le pied opposé à la dysfonction sur la table. Glisser le genou sous l’épaule opposée à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Poser la main controlatérale à la dysfonction sur le sommet de la tête du sujet avec l’avant-bras au contact de la face latérale de la tête. Contrôler par la main homolatérale à la dysfonction l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale et cervicale en inclinaison homolatérale à la dysfonction. Puis ajouter une translation controlatérale du tronc en écartant le genou du praticien de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Enfin, amener en rotation controlatérale la tête du sujet jusqu’à percevoir la rotation de la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison de la tête controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale et rotation controlatérale – À répéter trois fois."}],"images":[]},"47":{"source":"OSTPRA2 — ligne vidéo 47","titleSource":"Dysfonction d’une vertèbre dorsale (D1-D6), en ERdSd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. PRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Enserrer la tête du sujet entre le bras et l’avant-bras céphalique, la main est au contact de l’occiput. Contacter par les doigts de la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en flexion en y associant une translation postérieure du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Amener la tête du sujet en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et légèrement en rotation homolatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et flexion – À répéter trois fois."}],"images":[]},"48":{"source":"OSTPRA2 — ligne vidéo 48","titleSource":"Dysfonction d’une vertèbre dorsale (D1-D3), en FRdSd (E.M.)","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dorsales et thorax – dorsale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. PRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique repose sur le front du sujet, l’avant-bras contacte la face latérale de la tête. Contrôler par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser sur la main et l’avant-bras du praticien et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et extension – À répéter trois fois."}],"images":[]},"49":{"source":"OSTPRA2 — ligne vidéo 49","titleSource":"Dysfonction costo-transversaire de la 1re côte, en élévation. Technique structurelle","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dorsales et thorax – costo-vertébrale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. PRATICIEN Debout derrière le sujet. Poser le pied controlatéral à la dysfonction sur la table et glisser le genou sous l’épaule du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer le bord radial de l’articulation inter-phalangienne proximale de l’index de la main homolatérale à la dysfonction sur la face supérieure de la première côte, en avant du trapèze. La main controlatérale empaume la région fronto-pariétale. Le coude vient au contact de la partie antérieure de l’épaule du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison homolatérale à la dysfonction et en rotation controlatérale jusqu’à la perception du relâchement fascial de la zone. Exercer sur la côte une pression progressive vers le bas et en direction de la hanche controlatérale du sujet jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers le bas et la hanche opposée en fin de mouvement et d’expiration."}],"images":[]},"50":{"source":"OSTPRA2 — ligne vidéo 50","titleSource":"Dysfonction costo-transversaire antéro-médiane, technique structurelle","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dorsales et thorax – costo-vertébrale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés. PRATICIEN Debout à la hauteur du thorax du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation controlatérale à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dehors en fin d’expiration."}],"images":[]},"51":{"source":"OSTPRA2 — ligne vidéo 51","titleSource":"Dysfonction costo-transversaire postéro latérale, technique structurelle","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dorsales et thorax – costo-vertébrale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés. PRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation homolatérale à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dedans en fin d’expiration."}],"images":[]},"52":{"source":"OSTPRA2 — ligne vidéo 52","titleSource":"Dysfonction costo-transversaire, composantes multiples, technique structurelle, assis","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dorsales et thorax – costo-vertébrale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon, la main controlatérale est posée sur l’épaule homolatérale à la dysfonction et la main homolatérale repose sur le grill costal controlatéral. PRATICIEN Assis à califourchon derrière le sujet légèrement décalé sur le côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien empaume le deltoïde homolatéral à la dysfonction. Contacter par le pisiforme de la main caudale l’articulation costo-transversaire en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en extension."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale vers l’avant, en fin d’expiration."}],"images":[]},"53":{"source":"OSTPRA2 — ligne vidéo 53","titleSource":"Dysfonction costo-transversaire antéro-médiane (E.M.)","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dorsales et thorax – costo-vertébrale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table. Amener la main homolatérale à la dysfonction sur l’épaule opposée PRATICIEN Debout du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction. Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dedans de l’angle costal postérieur."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation controlatérale à la dysfonction jusqu’à la barrière motrice de la zone."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tirer son coude vers le bas, vers l’arrière et en dehors et s’y opposer. Simultanément avec le pouce le praticien repousse l’angle costal postérieur en dehors. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation controlatérale la dysfonction – À répéter trois fois."}],"images":[]},"54":{"source":"OSTPRA2 — ligne vidéo 54","titleSource":"Dysfonction costo-transversaire postéro-latérale (E.M.)","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dorsales et thorax – costo-vertébrale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. Amener la main homolatérale à la dysfonction sur l’épaule opposée. PRATICIEN Debout du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dehors de l’angle costal postérieur."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation homolatérale à la dysfonction jusqu’à la barrière motrice de la zone."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’amener son coude homolatéral à la dysfonction en dehors et s’y opposer. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation homolatérale à la dysfonction – À répéter trois fois."}],"images":[]},"55":{"source":"OSTPRA2 — ligne vidéo 55","titleSource":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan sagittal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique crochète l’angle postérieur de la première côte. La tête du sujet repose sur l’avant-bras du praticien. Le pouce de la main caudale est en contact avec la partie antérieure de la première côte, sous la clavicule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à percevoir la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, amener la partie antérieure de la première côte en direction des pieds et tracter simultanément sa partie postérieure vers la tête. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois."}],"images":[]},"56":{"source":"OSTPRA2 — ligne vidéo 56","titleSource":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan frontal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main caudale vient au contact de la partie supérieure de la première côte. La main céphalique soutient l’occiput du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, pousser la première côte en direction des pieds. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois."}],"images":[]},"57":{"source":"OSTPRA2 — ligne vidéo 57","titleSource":"Dysfonction respiratoire des (1re à 6e côte), en élévation dans le plan sagittal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et sur le thorax afin de la guider et de la stabiliser. Le pouce de la main antérieure contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception, par sa main antérieure, d’un relâchement fascial sus-jacent du niveau à normaliser. Par la main postérieure, crocheter simultanément la côte en regard du même niveau"},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une expiration exagérer les leviers de flexion du rachis. Au relâchement, rechercher une nouvelle barrière motrice – À répéter trois fois"}],"images":[]},"58":{"source":"OSTPRA2 — ligne vidéo 58","titleSource":"Dysfonction respiratoire des (1re-6e côte), en élévation dans le plan frontal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphaliques soutiennent et guident le rachis dorsal et cervical, la main caudale par sa première commissure contacte la côte en dysfonction en regard de la ligne médio-axillaire."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion et une inclinaison du côté homolatéral à la dysfonction du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent de la côte en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale – À répéter trois fois."}],"images":[]},"59":{"source":"OSTPRA2 — ligne vidéo 59","titleSource":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan sagittal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La main caudale contacte par la première commissure la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser. Crocheter simultanément et postérieurement la côte en regard du même niveau."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en flexion et inclinaison homolatérale à la dysfonction – À répéter trois fois."}],"images":[]},"60":{"source":"OSTPRA2 — ligne vidéo 60","titleSource":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan frontal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant- bras et le thorax du praticien afin de la guider et de la stabiliser. La première commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en regard de la ligne médio-axillaire."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical et dorsal en flexion et en inclinaison homolatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale à la dysfonction – À répéter trois fois."}],"images":[]},"61":{"source":"OSTPRA2 — ligne vidéo 61","titleSource":"Dysfonction des (1re-2e côte), en abaissement dans le plan sagittal (E.M.). Technique dite en « bras de pompe »","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front. Le praticien le maintient par sa main céphalique. PRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1re ou de la 2e côte."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois."}],"images":[]},"62":{"source":"OSTPRA2 — ligne vidéo 62","titleSource":"Dysfonction des (1re-2e côte), en abaissement dans le plan frontal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front que le praticien maintient par sa main céphalique. PRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1re ou de la 2e côte."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois."}],"images":[]},"63":{"source":"OSTPRA2 — ligne vidéo 63","titleSource":"Dysfonction des (3e-10e côte), en abaissement, dans le plan sagittal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front coude vers le haut. PRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter de la main caudale l’angle postérieur de la 1re ou de la 2e côte. La main céphalique du praticien contacte le coude du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser son coude en direction de ses pieds et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois."}],"images":[]},"64":{"source":"OSTPRA2 — ligne vidéo 64","titleSource":"Dysfonction des (3e-10e côte), en abaissement, dans le plan frontal (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction. PRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le coude du sujet homolatéral à la dysfonction en passant par le dessus de sa tête. Sa main repose sur l’avant-bras du praticien. La 1re commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener une inclinaison thoracique controlatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de ramener latéralement le coude en direction du tronc et s’y opposer. Lors du relâchement, majorer l’inclinaison du tronc et la traction de la côte en dysfonction – À répéter trois fois."}],"images":[]},"65":{"source":"OSTPRA2 — ligne vidéo 65","titleSource":"Dysfonction des (11e-12e côte), en élévation (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée, le bras homolatéral est placé le long du corps. PRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction des pieds du sujet."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Sur l’expiration, demander au sujet de pousser le bassin contre la table, s’y opposer. Simultanément, le patient glisse le bras en direction de ses pieds. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en abaissant la côte – À répéter trois fois."}],"images":[]},"66":{"source":"OSTPRA2 — ligne vidéo 66","titleSource":"Dysfonction des (11e-12e côte), en abaissement (E.M.)","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dorsales et thorax – côtes. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée. Le membre supérieur homolatéral à la dysfonction est posé à la hauteur de la tête. PRATICIEN Debout à la hauteur du bassin, du côté opposé à dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"la main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction de la tête."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Fixer la côte à normaliser et demander au sujet d’amener son bassin vers le haut et en direction de la table. S’y opposer pendant 10 à 12 secondes. Lors de la phase d’expiration, étirer le carré des lombes en tractant le bassin en haut et en arrière – À répéter trois fois."}],"images":[]},"67":{"source":"OSTPRA2 — ligne vidéo 67","titleSource":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), position assise, à droite","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dorsales et thorax – cervico-dorsales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET assis en bord de table. PRATICIEN Debout derrière le sujet, poser le pied droit sur la table, le genou est sous le creux axillaire."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la pulpe du pouce gauche la face latérale droite de l’épineuse de la vertèbre en dysfonction. Les autres doigts sont posés sur la clavicule. Le coude est placé dans un axe horizontal. La main droite empaume la face latérale de la tête, le coude reposant sur l’épaule du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Écarter légèrement le genou droit de façon à induire une translation droite du niveau à normaliser. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement dans l’axe horizontal."}],"images":[]},"68":{"source":"OSTPRA2 — ligne vidéo 68","titleSource":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), en procubitus à droite","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dorsales et thorax – cervico-dorsales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, le menton est posé sur la table. PRATICIEN Debout, à la hauteur du thorax du sujet, du côté opposé à la postériorité de la vertèbre en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce gauche contacte la face latérale gauche de l’épineuse. Les autres doigts sont posés sur la clavicule. L’avant bras est horizontal dans la direction de l’épaule opposée au sujet. La main droite est posée en conque sur la face latérale droite de la tête (ne pas écraser l’oreille)."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement en direction de l’épaule droite du sujet."}],"images":[]},"69":{"source":"OSTPRA2 — ligne vidéo 69","titleSource":"Dysfonction de la région cervico-dorsale (C7-D2) composantes multiples à droite","category":"Dorsales et thorax – cervico-dorsales","method":"Technique structurelle","intro":"Dorsales et thorax – cervico-dorsales. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En latérocubitus, les membres inférieurs sont fléchis et les mains placées entre les genoux. L’épaule du côté de la table est dégagée vers l’avant et en direction des pieds. PRATICIEN Debout en fente avant gauche à la hauteur de la ceinture scapulaire."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Soulever la tête du sujet et la maintenir fermement à l’aide du bras et de l’avant-bras gauche, la main recouvre l’occiput. Poser le thorax sur l’épaule gauche du sujet. Appliquer la pulpe du pouce droit sur la face latérale du processus épineux de la vertèbre sous-jacente à la dysfonction, les doigts libres étant étalés sur la région dorsale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en inclinaison gauche, en translation latérale droite et en rotation droite. Associer ces composantes de mouvement avec celle de flexion, extension ou compression, à la recherche de la convergence de mise en tension de la zone en dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant les résultantes de tension, le praticien, par l’intermédiaire de sa main droite (placée sur l’épineuse) majore la rotation gauche par un mouvement de haute vélocité, basse amplitude (HBVA)."}],"images":[]},"70":{"source":"OSTPRA2 — ligne vidéo 70","titleSource":"Dysfonction de l’occiput, en postériorité à droite","category":"Cervicales – occiput","method":"Thrust","intro":"Cervicales – occiput. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet en fente latérale, légèrement décalé du côté homolatéral à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le menton par la main controlatérale, l’avant-bras se positionne légèrement en avant de l’oreille du sujet. Contacter l’écaille occipitale par le bord radial de la métacarpo-phalangienne de l’index de la main homolatérale, en arrière de la mastoïde. L’avant-bras est horizontal dans l’axe des yeux du sujet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale à la dysfonction de la tête. Placer l’occiput en légère extension. Exercer une légère pression par son sternum sur la tête du sujet et une pression de l’index sur l’occiput jusqu’à la barrière motrice dans le plan des facettes articulaires de l’occiput."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction des yeux du sujet."}],"images":[]},"71":{"source":"OSTPRA2 — ligne vidéo 71","titleSource":"Dysfonction de l’Occiput, en translation à droite","category":"Cervicales – occiput","method":"Thrust","intro":"Cervicales – occiput. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90° du côté opposé à la dysfonction. PRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente, les doigts en direction des pieds, empaument la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index et le majeur sont de part et d’autre du muscle sterno-cléido- mastoïdien. La main sus-jacente applicatrice est posée sur la face latérale de la tête. Le talon de la main est en contact avec la branche horizontale du maxillaire inférieur."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener simultanément la tête en inclinaison homolatérale à la dysfonction et en translation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de la main sus-jacente applicatrice en majorant l’inclinaison homolatérale. La main sous-jacente accompagnant le mouvement."}],"images":[]},"72":{"source":"OSTPRA2 — ligne vidéo 72","titleSource":"Dysfonction articulaire globale Occiput Atlas Axis (OAA)","category":"Cervicales – OAA","method":"Thrust","intro":"Cervicales – OAA. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90°. PRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente empaume la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index de la main sus-jacente est sur la tempe. Le majeur sous le malaire, les deux autres doigts sous le menton, le pouce contacte l’écaille occipitale. Les deux avant-bras sont dans le prolongement du sterno- cléido-mastoïdien, le coude sus-jacent au dessus du sternum."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tout en maintenant les avant-bras dans l’axe vertébral, effectuer un mouvement hélicoïdal en légère traction et en rotation de la tête jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le mouvement hélicoïdal. Répéter la manœuvre en rotation opposée."}],"images":[]},"73":{"source":"OSTPRA2 — ligne vidéo 73","titleSource":"Dysfonction de l’Atlas, en postériorité à droite","category":"Cervicales – atlas","method":"Thrust","intro":"Cervicales – atlas. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo- phalangienne de l’index. La main et l’avant-bras sont en direction des yeux et parallèles au plan de la table."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale de la tête. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation."}],"images":[]},"74":{"source":"OSTPRA2 — ligne vidéo 74","titleSource":"Dysfonction de l’Atlas, en translation droite","category":"Cervicales – atlas","method":"Thrust","intro":"Cervicales – atlas. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo- phalangienne de l’index, la main et l’avant-bras sont en direction des yeux."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale à la dysfonction. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du sol."}],"images":[]},"75":{"source":"OSTPRA2 — ligne vidéo 75","titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite (variante)","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Cervicales – facettes cervicales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN À la tête du sujet en fente latérale du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume la face latérale du visage du sujet. La main homolatérale contacte, par la métacarpo- phalangienne de l’index, la partie postéro-latérale de l’apophyse transverse de la vertèbre en dysfonction. Le pouce est posé sur la branche horizontale de la mandibule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de rotation controlatérale."}],"images":[]},"76":{"source":"OSTPRA2 — ligne vidéo 76","titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite; prise mentonnière","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Cervicales – facettes cervicales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo- phalangienne de l’index. Veiller à ce que la main et l’avant-bras droits soient dans le plan des facettes articulaires."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale et l’inclinaison homolatérale de la tête. Ajouter une légère extension. Exercer une pression indexielle sur l’apophyse articulaire jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en rotation controlatérale dans le plan des facettes articulaires."}],"images":[]},"77":{"source":"OSTPRA2 — ligne vidéo 77","titleSource":"Dysfonction facettaire des cervicales (C2-C6), en translation droite","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Cervicales – facettes cervicales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo- phalangienne de l’index. Le pouce est posé sur la branche horizontale de la mandibule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en légère inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de translation."}],"images":[]},"78":{"source":"OSTPRA2 — ligne vidéo 78","titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à gauche; sujet assis","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Cervicales – facettes cervicales. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. PRATICIEN Debout, devant le sujet, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main homolatérale applicatrice contacte l’apophyse articulaire de la vertèbre en dysfonction par la pulpe du médius. La main controlatérale est sur la face latérale de la tête."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en légère extension. Exercer par le médius une pression sur l’apophyse articulaire jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation dans le plan des facettes articulaires."}],"images":[]},"79":{"source":"OSTPRA2 — ligne vidéo 79","titleSource":"Dysfonction des cervicales (C2-C7), en ERdSd (E.M.)","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Cervicales – cervicales. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume l’écaille de l’occiput controlatéral. La main homolatérale applicatrice contacte par la métacarpo- phalangienne de l’index l’apophyse transverse de la vertèbre en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner la tête vers la main applicatrice et vers l’arrière. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une inclinaison homolatérale, une translation, une rotation controlatérale et une flexion – À répéter 3 fois."}],"images":[]},"80":{"source":"OSTPRA2 — ligne vidéo 80","titleSource":"Dysfonction des cervicale (C2-C7), en FRdSd (E.M.)","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Cervicales – cervicales. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo- phalangienne de l’index."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et vers son épaule homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une extension, une inclinaison homolatérale, une translation et une rotation controlatérale – À répéter 3 fois."}],"images":[]},"81":{"source":"OSTPRA2 — ligne vidéo 81","titleSource":"Dysfonction Atloïdo-axoïdienne, en rotation droite (E.M.)","category":"Cervicales – Atlas – axis","method":"Énergie musculaire","intro":"Cervicales – Atlas – axis. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’écaille de l’occiput. La main homolatérale contacte la face latérale du visage du sujet, en avant de l’oreille."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en rotation et en légère translation controlatérales à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner les yeux avec insistance en direction de la dysfonction pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation et la translation controlatérales – À répéter 3 fois."}],"images":[]},"82":{"source":"OSTPRA2 — ligne vidéo 82","titleSource":"Dysfonction Occipito-atloïdienne, en ESgRd (E.M.)","category":"Cervicales – occiput atlas","method":"Énergie musculaire","intro":"Cervicales – occiput atlas. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo- phalangienne de l’index."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en rotation et en légère translation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton vers le plafond et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale, en rotation controlatérale et en flexion – À répéter 3 fois."}],"images":[]},"83":{"source":"OSTPRA2 — ligne vidéo 83","titleSource":"Dysfonction Occipito-atloïdienne, en FSgRd (E.M.)","category":"Cervicales – occiput – atlas","method":"Énergie musculaire","intro":"Cervicales – occiput – atlas. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo- phalangienne de l’index."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en rotation et en légère translation controlatérale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton en direction de ses pieds et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison homolatérale et en rotation controlatérale – À répéter 3 fois."}],"images":[]},"85":{"source":"OSTPRA3 — ligne vidéo 85","titleSource":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE, à droite","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"Membre supérieur – articulation sterno-claviculaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. PRATICIEN Debout à la hauteur du thorax du sujet, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre supérieur homolatéral à la dysfonction par la main céphalique du praticien. La main caudale applicatrice contacte par l’éminence hypothénar le bord antérieur de l’extrémité interne de la clavicule les doigts reposent sur trapèze."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule. Dans le même axe, exercer une légère traction sur le membre supérieur et porter le moignon de l’épaule en direction du plafond. Majorer par la main applicatrice la pression sur l’extrémité de la clavicule en direction de la table jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans l’axe de la clavicule et en direction de la table en fin de mouvement."}],"images":[]},"86":{"source":"OSTPRA3 — ligne vidéo 86","titleSource":"Dysfonction sus-sternale de la clavicule, à droite","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"Membre supérieur – articulation sterno-claviculaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. PRATICIEN Debout à la hauteur de la tête du sujet, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique prend en berceau le membre supérieur homolatéral à la dysfonction. La main caudale applicatrice contacte, par l’éminence hypothénar, la face supérieure de l’extrémité interne de la clavicule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule en exerçant une légère traction. Par la main applicatrice, majorer la pression sur l’extrémité interne de la clavicule, en direction des pieds du sujet, jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant la traction sur le membre supérieur, porter le thrust par la main applicatrice en direction des pieds du sujet."}],"images":[]},"87":{"source":"OSTPRA3 — ligne vidéo 87","titleSource":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE (E.M.), à droite","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"Membre supérieur – articulation sterno-claviculaire. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction, la main de l’épaule en dysfonction est posée sur l’épaule du praticien. PRATICIEN Debout à la hauteur du thorax, face au sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Maintenir le poignet du patient et contacter par l’index et le majeur de la main applicatrice le bord antérieur de l’extrémité interne de la clavicule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le bras et l’épaule du sujet en direction du plafond jusqu’à percevoir, par la main applicatrice, la barrière motrice sterno-claviculaire."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tracter l’épaule et le bras en direction de la table et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par élévation de l’épaule – À répéter 3 fois."}],"images":[]},"88":{"source":"OSTPRA3 — ligne vidéo 88","titleSource":"DYSFONCTION SUS-STERNALE DE LA CLAVICULE (E.M.), à gauche","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"Membre supérieur – articulation sterno-claviculaire. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. L’épaule en dysfonction est légèrement en dehors de la table. PRATICIEN Debout face au sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main distale saisit le poignet du sujet. La main applicatrice contacte par l’index et le majeur, le bord antérieur de l’extrémité interne de la clavicule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur en rétropulsion, en rotation interne et en légère abduction, jusqu’à percevoir par la main applicatrice, la barrière motrice sterno-claviculaire."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de soulever le membre supérieur et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par un abaissement du membre supérieur – À répéter 3 fois."}],"images":[]},"89":{"source":"OSTPRA3 — ligne vidéo 89","titleSource":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation antérieure, à gauche","category":"Membre supérieur – articulation acromio-claviculaire","method":"Technique structurelle","intro":"Membre supérieur – articulation acromio-claviculaire. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction. PRATICIEN Debout, derrière le sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main applicatrice contacte par le pisiforme la partie la plus postérieure de la face supéro- externe de la clavicule. La main opposée empaume la partie proximale de l’avant-bras."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Fixer la clavicule en rotation postérieure en exerçant, par la main applicatrice, une pression horizontale vers l’arrière."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’avant et se terminant en position de rétropulsion."}],"images":[]},"90":{"source":"OSTPRA3 — ligne vidéo 90","titleSource":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation postérieure à gauche","category":"Membre supérieur – articulation acromio-claviculaire","method":"Technique structurelle","intro":"Membre supérieur – articulation acromio-claviculaire. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction. PRATICIEN Debout, derrière le sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume l’avant-bras. La main applicatrice contacte par le pisiforme la partie la plus antérieure de la face supéro‑externe la clavicule."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer par le pisiforme une pression en direction de la table de façon à fixer la clavicule en rotation antérieure."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’arrière et se terminant en position d’antépulsion et adduction."}],"images":[]},"91":{"source":"OSTPRA3 — ligne vidéo 91","titleSource":"DYSFONCTION GLÉNO-HUMÉRALE, en antériorité, à gauche","category":"Membre supérieur – gleno-humérale","method":"Thrust","intro":"Membre supérieur – gleno-humérale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le coude du sujet. La face antérieure de la cuisse contacte la face supéro-interne du bras du sujet. L’éminence hypothénar de la main applicatrice contacte la tête humérale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur le membre supérieur en l’amenant en adduction, puis majorer la pression sur la tête de l’humérus en direction du sol jusqu’à percevoir la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en direction du sol."}],"images":[]},"92":{"source":"OSTPRA3 — ligne vidéo 92","titleSource":"DYSFONCTION HUMÉRO-ULNAIRE, en abduction, à gauche","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"Membre supérieur – huméro-ulnaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du bassin, en fente avant, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur distal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en adduction. Majorer par la main interne la pression sur le coude de dedans en dehors jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dedans en dehors."}],"images":[]},"93":{"source":"OSTPRA3 — ligne vidéo 93","titleSource":"DYSFONCTION HUMÉRO-ULNAIRE en adduction, à droite","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"Membre supérieur – huméro-ulnaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du bassin en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur proximal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale par rapport au sol."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en abduction. Majorer par la main externe la pression sur le coude de dehors en dedans jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dehors en dedans."}],"images":[]},"94":{"source":"OSTPRA3 — ligne vidéo 94","titleSource":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"Membre supérieur – huméro-radiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. Le coude du sujet est posé sur la face antérieure de la cuisse du praticien. PRATICIEN Debout à la hauteur du thorax, le genou du membre inférieur proximal est posé sur la table."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume le poignet du sujet. L’index et le majeur de la main opposée contactent le pli antérieur du coude."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener l’avant-bras en flexion et en supination. La main applicatrice exerce une pression sur la tête radiale en la tractant jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en majorant la traction."}],"images":[]},"95":{"source":"OSTPRA3 — ligne vidéo 95","titleSource":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"Membre supérieur – huméro-radiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du thorax, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le poignet du sujet. Le pouce de la main proximale applicatrice contacte la convexité postérieure de la tête radiale en dysfonction, les autres doigts soutiennent la face interne du coude."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Placer l’avant-bras en extension incomplète de façon à permettre le jeu articulaire. Amener la main du sujet en flexion palmaire et en inclinaison ulnaire."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation interne et l’extension du coude. Simultanément, le pouce applicateur exerce une pression sur la tête radiale. En fin de mouvement, la main du sujet vient en butée sur la hanche du praticien de façon à éviter l’hyper-extension."}],"images":[]},"96":{"source":"OSTPRA3 — ligne vidéo 96","titleSource":"DYSFONCTION HUMÉRO-RADIALE, en postériorité (variante), à droite","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"Membre supérieur – huméro-radiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en pronation entre le membre supérieur interne et le thorax à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La main externe applicatrice contacte, par la métacarpo- phalangienne de l’index, la partie postérieure de la tête radiale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension. La main applicatrice exerce une pression sur le coude de l’arrière vers l’avant jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du plafond."}],"images":[]},"97":{"source":"OSTPRA3 — ligne vidéo 97","titleSource":"DYSFONCTION RADIO-CARPIENNE DU SCAPHOÏDE OU DU SEMI-LUNAIRE, en postériorité, à gauche","category":"Membre supérieur – radio-carpienne","method":"Snap","intro":"Membre supérieur – radio-carpienne. Snap.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la main est placée en dehors de la table. PRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Enserrer le poignet entre les pouces et les index des deux mains. Les pouces superposés contactent la partie supérieure du scaphoïde ou du semi-lunaire. Les index soutiennent la face palmaire de la main."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » sur l’un ou l’autre des deux os, en direction du sol."}],"images":[]},"98":{"source":"OSTPRA3 — ligne vidéo 98","titleSource":"DYSFONCTION RADIO-CARPIENNE, en adduction, à gauche","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"Membre supérieur – radio-carpienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main externe contacte le bord ulnaire des os du carpe."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en adduction jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main externe de dehors en dedans."}],"images":[]},"99":{"source":"OSTPRA3 — ligne vidéo 99","titleSource":"DYSFONCTION RADIO-CARPIENNE, en abduction, à gauche","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"Membre supérieur – radio-carpienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main interne contacte le bord radial des os du carpe."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en abduction jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main interne de dedans en dehors."}],"images":[]},"100":{"source":"OSTPRA3 — ligne vidéo 100","titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DES MÉDIO-CARPIENNES, à droite","category":"Membre supérieur – médio-carpienne","method":"Technique structurelle","intro":"Membre supérieur – médio-carpienne. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le coude est fléchi à 90°. PRATICIEN Debout en fente avant les épaules dirigées du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains recouvrent la région carpienne antérieure et postérieure. Les éminences thénars sont placées perpendiculairement à l’axe de l’avant-bras. Les pouces se croisent sur la première commissure."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Les éminences thénar majorent la compression sur les os du carpe jusqu’à la barrière motrice et la maintiennent."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fermer la main avec force quelques secondes puis, au relâchement, majorer la compression – À répéter 3 fois."}],"images":[]},"101":{"source":"OSTPRA3 — ligne vidéo 101","titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DES INTER-CARPIENNES, à gauche","category":"Membre supérieur – inter-carpiennes","method":"Snap","intro":"Membre supérieur – inter-carpiennes. Snap.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. PRATICIEN Debout en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux pouces sont superposés sur la partie postérieure de l’espace inter-carpien en dysfonction. Les autres doigts maintiennent la partie antérieure du poignet."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » en direction du sol."}],"images":[]},"102":{"source":"OSTPRA3 — ligne vidéo 102","titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DE LA TRAPÉZO-MÉTACARPIENNE, à droite","category":"Membre supérieu – trapézo-metacarpienne","method":"Thrust","intro":"Membre supérieu – trapézo-metacarpienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus. PRATICIEN Debout à la hauteur de la main du sujet, du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le premier rayon de la main du sujet. Le pouce contacte la base postérieure du premier métacarpien. La main proximale empaume l’extrémité distale de l’avant-bras, le pouce de la main proximale se superposant au premier."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Les pouces exercent une pression progressive sur la base métacarpienne en dedans et vers l’extrémité distale du pouce jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la pression sur la base métacarpienne jusqu’à percevoir la décoaptation de l’articulation."}],"images":[]},"103":{"source":"OSTPRA3 — ligne vidéo 103","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation interne, à gauche","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT Assis en bord de table, les pieds sont posés au sol, les mains sont en appui sur la table. Placer la cheville homolatérale à la dysfonction sur le genou opposé, l’ensemble est stabilisé par le genou du praticien. PRATICIEN Debout face au patient, en fente avant, du côté opposé à l’articulation en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main proximale établit un contact, par la métacarpo- phalangienne de l’index, avec la région inguinale homolatérale à la dysfonction. La main opposée du praticien empaume la face interne du genou."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à incliner et tourner le tronc et la tête légèrement du côté opposé à la dysfonction. Majorer la rotation externe de la hanche jusqu’à la barrière motrice en poussant le genou du patient en direction du sol. Majorer son contact inguinal en appuyant en direction de la table."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à pousser son genou vers le haut et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation externe de la hanche – À répéter trois fois. En fin de technique, porter le thrust en majorant à la fois la rotation externe et la pression au niveau de l’aine."}],"images":[]},"104":{"source":"OSTPRA3 — ligne vidéo 104","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation externe, à droite","category":"Membre inférieur – coxo-fémorale","method":"Énergie musculaire","intro":"Membre inférieur – coxo-fémorale. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°, la tête est tournée du côté de la dysfonction. PRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit la cheville homolatérale à la dysfonction du patient. Le talon de la main céphalique contacte la face postérieure du grand trochanter après avoir refoulé les tissus musculaires."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale majore la rotation interne de la hanche, la main céphalique exerce une pression progressive sur le grand trochanter en direction de la table."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Majorer trois fois de suite la rotation interne et la pression sur le grand trochanter puis demander au sujet de tourner la tête du côté opposé à la dysfonction. Porter le thrust en direction de la table."}],"images":[]},"105":{"source":"OSTPRA3 — ligne vidéo 105","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en abduction, à gauche","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral sur le côté de la dysfonction. PRATICIEN Debout derrière le sujet à la hauteur du bassin."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale soutient en prise berceau le membre inférieur en dysfonction. La main céphalique contacte par la métacarpo-phalangienne de l’index la région inguinale homolatérale. Le pelvis du sujet est stabilisé par le bassin du praticien."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en légère extension. Amener le membre inférieur en dysfonction en légère flexion de hanche et adduction jusqu’à la barrière motrice. Le praticien majore le contact inguinal de la main céphalique par un mouvement antérieur de son pelvis."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’adduction et la pression inguinale."}],"images":[]},"106":{"source":"OSTPRA3 — ligne vidéo 106","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en adduction, à droite","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction. Le membre inférieur sous‑jacent est en flexion de hanche et de genou. PRATICIEN Debout derrière le sujet à la hauteur du pelvis pour le stabiliser."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur en dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en abduction puis majorer l’appui sur le grand trochanter jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du genou fléchi sous-jacent en majorant à la fois l’abduction et la pression sur le grand trochanter."}],"images":[]},"107":{"source":"OSTPRA3 — ligne vidéo 107","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en flexion, à droite","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. PRATICIEN Debout à la hauteur des cuisses, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur homolatéral à la dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en extension jusqu’à la barrière motrice et majorer le contact trochantérien."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’extension et la pression sur le grand trochanter."}],"images":[]},"108":{"source":"OSTPRA3 — ligne vidéo 108","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en antériorité classique, à droite","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table. PRATICIEN Debout, en bout de table aux pieds du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale et postérieure du tibia du membre inférieur en dysfonction. La main interne empaume l’extrémité distale et antérieure du tibia."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Le praticien cherche à amener la hanche en adduction et en rotation interne de hanche jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Soulever le membre inférieur de façon à permettre une adduction de la hanche au-delà de l’axe médian du corps. Le praticien transfert son poids sur la jambe externe de façon à amener le membre inférieur en abduction et rotation externe. Il transfert ensuite son poids sur la jambe interne pour porter un thrust en majorant à la fois l’adduction et la rotation interne. Renouveler la manœuvre si nécessaire."}],"images":[]},"109":{"source":"OSTPRA3 — ligne vidéo 109","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en postériorité, à droite","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°. PRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main externe et le sillon delto‑pectoral calent le genou fléchi du membre inférieur en dysfonction. La main interne stabilise le pelvis par un contre- appui sur l’épine iliaque antéro- supérieure controlatérale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Exercer quatre séries de trois pressions. D’abord dans l’axe fémoral en direction de la table, puis en adduction, puis en abduction puis en flexion. La mise en tension se termine par une série de circumduction de plus en plus ample jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de circumduction en majorant l’abduction et la rotation externe dans un mouvement de haute vélocité."}],"images":[]},"110":{"source":"OSTPRA3 — ligne vidéo 110","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE dans un axe transversal, à droite","category":"Membre inférieur – coxo-fémorale","method":"Technique structurelle","intro":"Membre inférieur – coxo-fémorale. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi. PRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains superposées empaument la partie supéro- interne de la cuisse du membre inférieur en dysfonction. La face externe du genou est stabilisée par le sternum du praticien."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la compression des tissus de la face interne de la cuisse."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"À l’aide du sternum, exercer une pression sur le genou. Les deux mains tractent la cuisse en direction du haut et du dehors – À répéter plusieurs fois dans un mouvement de pompage."}],"images":[]},"111":{"source":"OSTPRA3 — ligne vidéo 111","titleSource":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE, en antériorité, à droite","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"Membre inférieur – coxo-fémorale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi. PRATICIEN Debout à la hauteur du pelvis, en fente avant du côté de la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le genou du membre inférieur en dysfonction et l’avant-bras stabilise la face interne du segment jambier. La main céphalique stabilise le pelvis par un contact sur l’épine iliaque antéro-supérieure opposée."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en rotation interne jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table."}],"images":[]},"112":{"source":"OSTPRA3 — ligne vidéo 112","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en abduction, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table. PRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou, les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’adduction du genou jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice interne de dedans en dehors."}],"images":[]},"113":{"source":"OSTPRA3 — ligne vidéo 113","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en adduction, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table. PRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou. Les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’abduction du genou jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice externe de dehors en dedans."}],"images":[]},"114":{"source":"OSTPRA3 — ligne vidéo 114","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table. PRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du praticien."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer, par les deux mains applicatrices, la pression sur la tubérosité tibiale antérieure vers l’arrière jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’arrière."}],"images":[]},"115":{"source":"OSTPRA3 — ligne vidéo 115","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table. PRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du praticien."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Tracter, par les deux mains applicatrices, le plateau tibial vers l’avant jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’avant."}],"images":[]},"116":{"source":"OSTPRA3 — ligne vidéo 116","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation interne, à droite","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou. PRATICIEN Debout à la hauteur de la jambe, en fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial interne."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation externe et en flexion complète du genou jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale."}],"images":[]},"117":{"source":"OSTPRA3 — ligne vidéo 117","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation externe, à droite","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou. PRATICIEN Debout en fente avant à la hauteur de la jambe en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial externe."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation interne et en flexion complète du genou jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale."}],"images":[]},"118":{"source":"OSTPRA3 — ligne vidéo 118","titleSource":"DYSFONCTION DU MÉNISQUE MÉDIAL, en postériorité et en extension, à droite","category":"Membre inférieur – fémoro-tibiale","method":"Technique structurelle","intro":"Membre inférieur – fémoro-tibiale. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°. PRATICIEN Debout à la hauteur du genou."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume la face plantaire du pied. La main céphalique empaume la partie supérieure du genou. L’index contacte l’interligne fémoro-tibial interne en regard de la corne antérieure du ménisque interne en dysfonction."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le tibia en rotation externe et en abduction pour ouvrir le compartiment interne. Ramener le talon du sujet sur la table. Puis tourner la main céphalique de telle façon à ce que le pouce remplace l’index au contact du ménisque médial et que les autres doigts soutiennent le genou."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"La normalisation dynamique se fait en amenant simultanément le genou en extension complète, en adduction et en rotation interne."}],"images":[]},"119":{"source":"OSTPRA3 — ligne vidéo 119","titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en translation interne, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table. PRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité inférieure de la cuisse, au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité supérieure du tibia, en dessous de l’interligne articulaire."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial interne de dedans en dehors jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne de dedans en dehors."}],"images":[]},"120":{"source":"OSTPRA3 — ligne vidéo 120","titleSource":"DYSFONCTION FÉMORO-TIBIALE, en translation externe, à gauche","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"Membre inférieur – fémoro-tibiale. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table. PRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité supérieure du tibia au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité inférieure de la cuisse en dessous de l’interligne articulaire."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial externe de dehors en dedans jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main externe de dehors en dedans."}],"images":[]},"121":{"source":"OSTPRA3 — ligne vidéo 121","titleSource":"DYSFONCTION DU MÉNISQUE MÉDIAL en postériorité, en flexion, à droite","category":"Membre inférieur – fémoro-tibiale","method":"Technique structurelle","intro":"Membre inférieur – fémoro-tibiale. Technique structurelle.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou sont fléchis à 90°. PRATICIEN Debout à la hauteur du genou."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inférieure du segment jambier en dysfonction. Les doigts de la main céphalique contactent l’interligne articulaire fémoro- tibial interne, en regard du ménisque médial. La face externe du genou est stabilisée par le sternum du praticien."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou en abduction et en rotation externe afin de favoriser l’ouverture du compartiment articulaire interne."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"La main caudale amène le genou en rotation interne et en flexion complète du genou dans un mouvement dynamique. La main céphalique reste, quant à elle, au contact du ménisque."}],"images":[]},"122":{"source":"OSTPRA3 — ligne vidéo 122","titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE SUPÉRIEURE, en postériorité, à gauche","category":"Membre inférieur – fibulo-tibiale supérieure","method":"Thrust","intro":"Membre inférieur – fibulo-tibiale supérieure. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°. PRATICIEN Debout à la hauteur du genou, en fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inféro-interne de la jambe. La métacarpo-phalangienne de l’index de la main céphalique contacte la face postérieure de la tête péronière formant ainsi un contre appui dans la fosse poplitée."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en flexion de hanche et de genou en y associant une rotation externe du segment jambier et une abduction de hanche jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale. La main céphalique restant au contact de la face postérieure de la fibula. Le sternum en appui sur la face antérieure du tibia accompagne le mouvement."}],"images":[]},"123":{"source":"OSTPRA3 — ligne vidéo 123","titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en antériorité, à gauche","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"Membre inferieur – fibulo-tibiale inférieur. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est posé sur la table. PRATICIEN Debout face au pied du sujet, en bout de table."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains empaument le pied. La pulpe du pouce externe contacte la face antérieure de la malléole externe, les autres doigts sont sur le talon. Le pouce de la main interne renforce l’appui initial."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en légère flexion dorsale. Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction de la table."}],"images":[]},"124":{"source":"OSTPRA3 — ligne vidéo 124","titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en postériorité, à droite","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"Membre inferieur – fibulo-tibiale inférieur. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, les pieds sont en dehors de la table. PRATICIEN Debout, en bout de table, face au pied du patient, la plante du pied contacte la cuisse du praticien."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main externe est en appui sur la face postérieure de la malléole externe, les autres doigts maintiennent et stabilisent l’avant-pied en légère flexion dorsale. Le pouce interne renforce l’appui initial."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction du sol."}],"images":[]},"125":{"source":"OSTPRA3 — ligne vidéo 125","titleSource":"DYSFONCTION DE LA TIBIO-TARSIENNE ARTICULAIRE GLOBALE, en décubitus ventral, à gauche","category":"Membre inférieur – tibio-tarsienne","method":"Lift","intro":"Membre inférieur – tibio-tarsienne. Lift.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°. PRATICIEN Debout à la hauteur du genou."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Le genou céphalique maintient la face postérieure de la cuisse au dessus de la fosse poplitée. Les deux mains, les doigts sont croisés en regard de la malléole interne, enserrent la cheville en dysfonction. Les avant-bras sont à l’horizontale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en position neutre et exercer une légère traction en direction du plafond jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Majorer la traction par une traction verticale (lift) des deux mains dans l’axe tibial."}],"images":[]},"126":{"source":"OSTPRA3 — ligne vidéo 126","titleSource":"ENTORSE TIBIO-TARSIENNE EXTERNE, à droite","category":"Membre inférieur – tibio-tarsienne","method":"Snap","intro":"Membre inférieur – tibio-tarsienne. Snap.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table. PRATICIEN Debout face au pied du patient, en bout de table."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon, le pouce contacte le col du talus. La main interne renforce l’appui en maintenant le coup de pied en légère flexion dorsale."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion dorsale du pied et ajouter une composante d’éversion jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur le talus par le pouce en « snap » vers l’arrière et le dedans."}],"images":[]},"127":{"source":"OSTPRA3 — ligne vidéo 127","titleSource":"DYSFONCTION DE LA TIBIO-TARSIENNE, en antériorité, à droite","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"Membre inférieur – tibio-tarsienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. PRATICIEN Debout à la hauteur de la cheville."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le talon. La première commissure de la main céphalique maintient la face antérieure du pilon tibial."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir le pied en légère flexion dorsale. La main céphalique majore la pression vers l’arrière jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction du sol."}],"images":[]},"128":{"source":"OSTPRA3 — ligne vidéo 128","titleSource":"DÉCOAPTATION DE LA TIBIO-TARSIENNE GLOBALE, à gauche","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"Membre inférieur – tibio-tarsienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table. PRATICIEN Position semi-accroupie en bout de table à la hauteur du pied du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains sont croisées sur le coup de pied, les bords cubitaux des deux mains contactent le col du talus."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en flexion dorsale et exercer une traction dans l’axe tibial jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains en majorant la traction du pied."}],"images":[]},"129":{"source":"OSTPRA3 — ligne vidéo 129","titleSource":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE ANTÉRO-INTERNE, à gauche","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"Membre inférieur – sous-astragalienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est en dehors de la table. PRATICIEN Debout entre les jambes du sujet, à la hauteur du pied en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. Le pisiforme de la main céphalique contact la tête du talus en dedans du tibial antérieur."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied successivement en inversion, en flexion dorsale, en éversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne."}],"images":[]},"130":{"source":"OSTPRA3 — ligne vidéo 130","titleSource":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE POSTÉRO-EXTERNE, à droite","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"Membre inférieur – sous-astragalienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table. PRATICIEN Debout en bout de table, à la hauteur du pied en dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. La main céphalique contacte par le pisiforme la tête du talus, en dehors de l’extenseur commun des orteils."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener successivement le pied en éversion, en flexion dorsale, en inversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne."}],"images":[]},"131":{"source":"OSTPRA3 — ligne vidéo 131","titleSource":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en varus, à gauche","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"Membre inférieur – sous-astragalienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé au membre inférieur en dysfonction. Les genoux sont fléchis, le pied sus-jacent est légèrement en retrait. PRATICIEN Debout à la hauteur des pieds."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le calcanéus en dysfonction. Le bord cubital de la main céphalique contacte la face supéro-externe du calcanéus."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène et maintient le calcanéus en valgus. Exercer par la main céphalique une pression progressive, en direction de la table, sur la face externe du calcanéus jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table."}],"images":[]},"132":{"source":"OSTPRA3 — ligne vidéo 132","titleSource":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en valgus, à droite","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"Membre inférieur – sous-astragalienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les genoux sont fléchis, le pied en dysfonction est en dehors de la table. PRATICIEN Debout en bout de table, à la hauteur des pieds du sujet."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Amener le talon en dysfonction en dehors de la table, le reste du pied est sur la table. La main caudale empaume et fixe l’avant-pied en éversion. La main céphalique empaume la face interne du calcanéus."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique maintient le calcanéus en valgus. La main caudale exerce une pression progressive, en direction de la table jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table."}],"images":[]},"133":{"source":"OSTPRA3 — ligne vidéo 133","titleSource":"DYSFONCTION DE LA CALCANÉO-CUBOÏDIENNE, en rotation interne (pronation), à gauche","category":"Membre inférieur – calcanéo-cuboïdienne","method":"Thrust","intro":"Membre inférieur – calcanéo-cuboïdienne. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table. PRATICIEN Debout face au pied du patient, en bout de table."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon en dysfonction, le pouce contacte le col du talus en avant de la malléole externe. La main opposée enserre entre le pouce et les autres doigts la face plantaire et dorsale du pied, jusqu’au 4e et 5e métatarsiens (sous l’interligne cuboïdo-métatarsien)"},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main externe fixe le talon, la main interne amène l’avant-pied en supination jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne en supination de l’avant-pied."}],"images":[]},"134":{"source":"OSTPRA3 — ligne vidéo 134","titleSource":"DYSFONCTION TALO-NAVICULAIRE, en rotation externe (supination), à droite","category":"Membre inférieur – talo-naviculaire","method":"Thrust","intro":"Membre inférieur – talo-naviculaire. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table. PRATICIEN Debout du côté de la dysfonction à la hauteur du pied du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’extrémité inférieure du segment jambier, l’index est sur le col du talus en dysfonction. La main caudale contacte la face supérieure et interne de l’avant pied, son index est sur la partie interne de l’os naviculaire."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène l’os naviculaire en pronation jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale en pronation, en direction de la table."}],"images":[]},"135":{"source":"OSTPRA3 — ligne vidéo 135","titleSource":"DYSFONCTION DE LA NAVICULO-CUBOÏDIENNE ARTICULAIRE GLOBALE, à droite","category":"Membre inférieur – naviculo-cuboïdienne","method":"Snap","intro":"Membre inférieur – naviculo-cuboïdienne. Snap.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le membre inférieur en dysfonction est en dehors de la table, le genou est fléchi. PRATICIEN Debout face au pied du patient, en fente avant."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains enserrent les bords interne et externe du pied. Les pouces sont superposés sur l’interligne articulaire naviculo-cuboïdien de la face plantaire, les autres doigts soutiennent la face dorsale du pied."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser le membre inférieur par plusieurs mouvements en piston jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"En fin de mouvement, porter le thrust en « snap » par les deux pouces en majorant la flexion plantaire et la pression sur l’interligne articulaire."}],"images":[]},"136":{"source":"OSTPRA3 — ligne vidéo 136","titleSource":"DYSFONCTION DE LA MÉTACARPO-PHALANGIENNE DE LA 1re PHALANGE, en flexion dorsale, à droite","category":"Membre inférieur – metatarso-phalangiennes","method":"Thrust","intro":"Membre inférieur – metatarso-phalangiennes. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table. PRATICIEN Debout sur le côté du pied en dysfonction à la hauteur du pied du patient."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume la face interne de l’avant-pied au niveau du premier rayon métatarsien en dysfonction. La pince pouce-index de la main caudale saisit la première phalange du gros orteil."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique amène le premier métatarsien en pronation. La main caudale majore la flexion plantaire de la première phalange du gros orteil jusqu’à la barrière motrice."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale, en flexion plantaire."}],"images":[]},"7":{"source":"OSTPRA1 — ligne vidéo 7","titleSource":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (E.M.)","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"Pelvis – sacro-ilium. Énergie musculaire.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. La main homolatérale à la dysfonction saisit le sommet de la têtière. Le membre inférieur en dysfonction est en flexion de hanche inférieure à 90°. PRATICIEN Debout en fente avant à la hauteur des jambes, la jambe gauche est dirigée vers la tête du patient. Le pied homolatéral du patient est posé sur l’épine ilium antéro- supérieure gauche du praticien."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la face interne du genou par sa main céphalique. Poser la main caudale sur l’articulation sacro-ilium."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser en flexion de hanche depuis une relative position d’extension jusqu’à la barrière motrice en postériorité de l’ilium."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Demander une abduction flexion de hanche. Répéter de hanche (poussée vers la manœuvre une seconde fois. le plafond) contre résistance Pour la troisième poussée, pendant 10 à 12 secondes le praticien invite le patient – Au relâchement, trouver à pousser en extension de telle la nouvelle barrière motrice vers sorte que la poussée exercée la flexion (quelques degrés) – soit supérieure à la résistance À répéter 3 fois. Puis demander du praticien, jusqu’à obtenir une adduction de hanche sur la rectitude du membre inférieur. le même principe – à répéter trois fois – Même chose en flexion de hanche. Ensuite, demander au patient de pousser en extension de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, gagner en légère"}],"images":[]},"18":{"source":"OSTPRA1 — ligne vidéo 18","titleSource":"DYSFONCTION DU SACRUM, en extension unilatérale sur axe horizontal, à droite","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"Pelvis – sacro-ilium. Thrust.","steps":[{"key":"position","logoKey":"position","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus la tête tournée du côté de la dysfonction. PRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction."},{"key":"mains","logoKey":"mains","label":"Position des mains","title":"Contacts et prises","body":"Contacter, avec le pisiforme de la main caudale, la base sacrée en dysfonction par un mouvement de « pas de vis » en direction céphalique. Renforcer la pression de la main caudale par la main céphalique."},{"key":"barriere","logoKey":"barriere","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en légère abduction et en rotation interne. Amener une pression sur la zone sous-facettaire vers la table jusqu’à la barrière motrice en flexion. Demander au patient de tourner la tête du côté opposé à la dysfonction."},{"key":"normalisation","logoKey":"normalisation","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers la flexion du sacrum en direction de la table."}],"images":[]}},"byTechniqueId":{"561":{"source":"PDF OSTPRA3 - Partie 50","intro":"Fiche associée à la dysfonction de la sous-talienne, calcanéus en valgus, à droite.","steps":[{"key":"position","label":"Position","logo":"assets/images/techniques/sous-talienne-valgus-droite/logo-position.png?v=3","photo":"assets/images/techniques/sous-talienne-valgus-droite/photo-position.webp?v=3","title":"Patient et praticien","body":"Patient en décubitus dorsal, genoux fléchis, pied en dysfonction en dehors de la table. Le praticien est debout en bout de table, à hauteur des pieds."},{"key":"mains","label":"Position des mains","logo":"assets/images/techniques/sous-talienne-valgus-droite/logo-mains.png?v=3","photo":"assets/images/techniques/sous-talienne-valgus-droite/photo-mains.webp?v=3","title":"Fixation de l’avant-pied et prise du calcanéus","body":"Le talon en dysfonction est amené en dehors de la table. La main caudale empaume et fixe l’avant-pied en éversion. La main céphalique empaume la face interne du calcanéus."},{"key":"barriere","label":"Barrière motrice","logo":"assets/images/techniques/sous-talienne-valgus-droite/logo-barriere.png?v=3","photo":"assets/images/techniques/sous-talienne-valgus-droite/photo-barriere.webp?v=3","title":"Mise en tension","body":"La main céphalique maintient le calcanéus en valgus. La main caudale exerce une pression progressive vers la table jusqu’à la barrière motrice."},{"key":"normalisation","label":"Normalisation","logo":"assets/images/techniques/sous-talienne-valgus-droite/logo-normalisation.png?v=3","photo":"assets/images/techniques/sous-talienne-valgus-droite/photo-normalisation.webp?v=3","title":"Thrust","body":"Porter le thrust par la main céphalique en direction de la table."}],"images":["assets/images/techniques/sous-talienne-valgus-droite/planche-photos.webp?v=3","assets/images/techniques/sous-talienne-valgus-droite/planche-texte.webp?v=3"]}}};
